// Scratch oracle (TypeScript compiler API, binder symbols): what Comp's body reads, whether its props escape, and
// which component owns every JSX element. Extends shrink/evidence-check/truth.cjs with: the `this` parameter, a rest
// parameter, `arguments` bound to the component, direct eval, decorators, by-binding element ownership and tag scope.
// Usage: node oracle.cjs <fixture.tsx>...  -> one JSON line per file.
const fs = require('fs');
const ts = require('/Users/gabe/Projects/caliper-fixtures/oracle-local/apps/oracle/node_modules/typescript');

const files = process.argv.slice(2);
const program = ts.createProgram(files, {
  noResolve: true, noLib: true, allowJs: true, jsx: ts.JsxEmit.Preserve, types: [], skipLibCheck: true,
  experimentalDecorators: false,
});
const checker = program.getTypeChecker();

const WRAP = new Set([ts.SyntaxKind.ParenthesizedExpression, ts.SyntaxKind.AsExpression, ts.SyntaxKind.NonNullExpression,
  ts.SyntaxKind.SatisfiesExpression, ts.SyntaxKind.TypeAssertionExpression, ts.SyntaxKind.ExpressionWithTypeArguments]);
const up = (n) => { while (n.parent && WRAP.has(n.parent.kind)) n = n.parent; return n; };
const peel = (e) => { while (e && WRAP.has(e.kind)) e = e.expression; return e; };
const isFn = (n) => ts.isFunctionDeclaration(n) || ts.isFunctionExpression(n) || ts.isArrowFunction(n) ||
  ts.isMethodDeclaration(n) || ts.isGetAccessor(n) || ts.isSetAccessor(n) || ts.isConstructorDeclaration(n);
const ASSIGN = new Set([ts.SyntaxKind.EqualsToken, ts.SyntaxKind.PlusEqualsToken, ts.SyntaxKind.MinusEqualsToken,
  ts.SyntaxKind.BarBarEqualsToken, ts.SyntaxKind.AmpersandAmpersandEqualsToken, ts.SyntaxKind.QuestionQuestionEqualsToken]);
const KNOWN_WRAPPERS = new Set(['memo', 'forwardRef', 'observer', 'assign']);

function memberIsRead(member) {
  const m = up(member), p = m.parent;
  if (ts.isCallExpression(p) && p.expression === m) return false;
  if (ts.isTaggedTemplateExpression(p) && p.tag === m) return false;
  if (ts.isDecorator(p)) return false; // `@props.dec` calls it with `this` = props
  if (ts.isBinaryExpression(p) && ASSIGN.has(p.operatorToken.kind) && p.left === m) return false;
  if ((ts.isPrefixUnaryExpression(p) || ts.isPostfixUnaryExpression(p)) &&
      (p.operator === ts.SyntaxKind.PlusPlusToken || p.operator === ts.SyntaxKind.MinusMinusToken)) return false;
  if (ts.isDeleteExpression(p)) return false;
  if ((ts.isForInStatement(p) || ts.isForOfStatement(p)) && p.initializer === m) return false;
  return true;
}

function findComp(sf) {
  let found = null, nobody = false, cls = false;
  const unwrap = (e) => {
    e = peel(e);
    if (!e) return null;
    if (ts.isFunctionExpression(e) || ts.isArrowFunction(e)) return { fn: e };
    if (ts.isCallExpression(e)) {
      const c = peel(e.expression);
      const name = ts.isIdentifier(c) ? c.text : ts.isPropertyAccessExpression(c) ? c.name.text : null;
      const first = e.arguments[0] && peel(e.arguments[0]);
      if (KNOWN_WRAPPERS.has(name)) return unwrap(e.arguments[0]);
      return { unknownCall: name, first: first && (ts.isArrowFunction(first) || ts.isFunctionExpression(first)) ? first : null };
    }
    if (ts.isClassExpression(e)) return { cls: true };
    return { other: ts.SyntaxKind[e.kind] };
  };
  for (const st of sf.statements) {
    if (ts.isFunctionDeclaration(st) && st.name && st.name.text === 'Comp') {
      if (st.body) found = { fn: st }; else nobody = true;
    } else if (ts.isVariableStatement(st)) {
      for (const d of st.declarationList.declarations) if (ts.isIdentifier(d.name) && d.name.text === 'Comp') found = unwrap(d.initializer);
    } else if (ts.isClassDeclaration(st) && st.name && st.name.text === 'Comp') cls = true;
    else if (ts.isExportAssignment(st) && !found) found = unwrap(st.expression);
