      if (kind === 'props') t.propsSpread = true;
    } else if (ts.isJsxOpeningElement(p) || ts.isJsxSelfClosingElement(p)) {
      hand('used as tag', id);
    } else if (ts.isPropertyAccessExpression(p) && ts.isJsxOpeningLikeElement(p.parent)) {
