const KNOWN_WRAPPERS = new Set(['memo', 'forwardRef', 'observer', 'assign']);

function memberIsRead(member) {
  const m = up(member), p = m.parent;
  if (ts.isCallExpression(p) && p.expression === m) return false;
  if (ts.isTaggedTemplateExpression(p) && p.tag === m) return false;
  if (ts.isDecorator(p)) return false; // `@props.dec` calls it with `this` = props
  if (ts.isBinaryExpression(p) && ASSIGN.has(p.operatorToken.kind) && p.left === m) return false;
  if ((ts.isPrefixUnaryExpression(p) || ts.isPostfixUnaryExpression(p)) &&
      (p.operator === ts.SyntaxKind.PlusPlusToken || p.operator === ts.SyntaxKind.MinusMinusToken)) return false;
  if (ts.isDeleteExpression(p)) return false;
  if ((ts.isForInStatement(p) || ts.isForOfStatement(p)) && p.initializer === m) return false;
  return true;
}

function findComp(sf) {
  let found = null, nobody = false, cls = false;
  const unwrap = (e) => {
    e = peel(e);
    if (!e) return null;
    if (ts.isFunctionExpression(e) || ts.isArrowFunction(e)) return { fn: e };
    if (ts.isCallExpression(e)) {
      const c = peel(e.expression);
      const name = ts.isIdentifier(c) ? c.text : ts.isPropertyAccessExpression(c) ? c.name.text : null;
      const first = e.arguments[0] && peel(e.arguments[0]);
      if (KNOWN_WRAPPERS.has(name)) return unwrap(e.arguments[0]);
      return { unknownCall: name, first: first && (ts.isArrowFunction(first) || ts.isFunctionExpression(first)) ? first : null };
    }
    if (ts.isClassExpression(e)) return { cls: true };
    return { other: ts.SyntaxKind[e.kind] };
  };
  for (const st of sf.statements) {
    if (ts.isFunctionDeclaration(st) && st.name && st.name.text === 'Comp') {
      if (st.body) found = { fn: st }; else nobody = true;
    } else if (ts.isVariableStatement(st)) {
      for (const d of st.declarationList.declarations) if (ts.isIdentifier(d.name) && d.name.text === 'Comp') found = unwrap(d.initializer);
    } else if (ts.isClassDeclaration(st) && st.name && st.name.text === 'Comp') cls = true;
    else if (ts.isExportAssignment(st) && !found) found = unwrap(st.expression);
  }
  if (found) return found;
  if (cls) return { cls: true };
  if (nobody) return { nobody: true };
  return null;
}

function truthOf(fn) {
  const t = { reads: [], handoff: false, why: [], propsSpread: false, tracked: new Map(), locals: new Map(), spreads: [] };
  const queue = [];
  const read = (key, at) => t.reads.push([at, key]);
  const hand = (why, node) => { t.handoff = true; t.why.push(why + (node ? '@' + (node.getSourceFile().getLineAndCharacterOfPosition(node.getStart()).line + 1) : '')); };
  const track = (nameNode, kind) => {
    const sym = checker.getSymbolAtLocation(nameNode);
    if (sym && !t.tracked.has(sym)) { t.tracked.set(sym, kind); queue.push(sym); }
  };
  const destructure = (pattern) => {
    for (const el of pattern.elements) {
      if (el.dotDotDotToken) { if (ts.isIdentifier(el.name)) track(el.name, 'rest'); else hand('rest pattern', el); continue; }
      const key = el.propertyName ?? el.name;
      let k = null;
      if (ts.isIdentifier(key) || ts.isStringLiteral(key) || ts.isNumericLiteral(key)) k = key.text;
      else if (ts.isComputedPropertyName(key) && ts.isStringLiteralLike(key.expression)) k = key.expression.text;
      if (k === null) { hand('computed key', el); continue; }
      read(k, el.getStart());
      if (ts.isIdentifier(el.name) && !el.initializer) {
        const s = checker.getSymbolAtLocation(el.name);
        if (s) t.locals.set(s, k);
      }
    }
  };
  const params = fn.parameters.filter((p) => !(ts.isIdentifier(p.name) && p.name.text === 'this'));
  const param = params[0];
  if (param) {
    if (param.dotDotDotToken) hand('rest parameter', param);
    else if (ts.isIdentifier(param.name)) track(param.name, 'props');
    else if (ts.isObjectBindingPattern(param.name)) destructure(param.name);
    else hand('array param', param);
  }
  // `arguments` of this function (not of a nested non-arrow function), direct eval.
  const scan = (n) => {
    if (ts.isIdentifier(n) && n.text === 'arguments' && !ts.isPropertyAccessExpression(n.parent)) {
      let f = n.parent;
      while (f && !(isFn(f) && !ts.isArrowFunction(f))) f = f.parent;
      if (f === fn) hand('arguments', n);
    }
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'eval') hand('direct eval', n);
    ts.forEachChild(n, scan);
  };
  scan(fn);
  while (queue.length) {
    const sym = queue.shift(), kind = t.tracked.get(sym);
    const visit = (node) => {
      if (ts.isIdentifier(node) && node.parent) {
        const p0 = node.parent;
        let isRef;
        if (ts.isShorthandPropertyAssignment(p0) && p0.name === node) isRef = checker.getShorthandAssignmentValueSymbol(p0) === sym;
        else {
          const decl = (ts.isBindingElement(p0) || ts.isParameter(p0) || ts.isVariableDeclaration(p0)) && p0.name === node;
          isRef = !decl && checker.getSymbolAtLocation(node) === sym;
        }
        if (isRef) classify(node, kind);
      }
      ts.forEachChild(node, visit);
    };
    visit(fn);
  }
  // A destructured local is the prop's value only while never written.
  const written = new Set();
  const w = (n) => {
    if (ts.isBinaryExpression(n) && ASSIGN.has(n.operatorToken.kind) && ts.isIdentifier(n.left)) written.add(checker.getSymbolAtLocation(n.left));
    if ((ts.isPrefixUnaryExpression(n) || ts.isPostfixUnaryExpression(n)) && ts.isIdentifier(n.operand)) written.add(checker.getSymbolAtLocation(n.operand));
    ts.forEachChild(n, w);
  };
  w(fn);
  for (const s of [...t.locals.keys()]) if (written.has(s) || (s.declarations || []).length > 1) t.locals.delete(s);
  t.reads.sort((a, b) => a[0] - b[0]);
  t.readKeys = [...new Set(t.reads.map((r) => r[1]))];
  return t;

  function classify(id, kind) {
    const cur = up(id), p = cur.parent;
    if (ts.isPropertyAccessExpression(p) && p.expression === cur) {
      if (memberIsRead(p)) read(p.name.text, id.getStart()); else hand('member call/write', id);
    } else if (ts.isElementAccessExpression(p) && p.expression === cur) {
      if (ts.isStringLiteral(p.argumentExpression) && memberIsRead(p)) read(p.argumentExpression.text, id.getStart());
      else hand('element access', id);
    } else if (ts.isVariableDeclaration(p) && p.initializer === cur && ts.isObjectBindingPattern(p.name)) {
      destructure(p.name);
    } else if (ts.isBinaryExpression(p) && p.operatorToken.kind === ts.SyntaxKind.EqualsToken && p.right === cur && ts.isObjectLiteralExpression(p.left)) {
      for (const prop of p.left.properties) {
        if ((ts.isPropertyAssignment(prop) || ts.isShorthandPropertyAssignment(prop)) && ts.isIdentifier(prop.name)) read(prop.name.text, prop.getStart());
        else hand('assignment pattern', prop);
      }
    } else if (ts.isJsxSpreadAttribute(p)) {
      t.spreads.push({ node: p, kind });
      if (kind === 'props') t.propsSpread = true;
    } else if (ts.isJsxOpeningElement(p) || ts.isJsxSelfClosingElement(p)) {
      hand('used as tag', id);
    } else if (ts.isPropertyAccessExpression(p) && ts.isJsxOpeningLikeElement(p.parent)) {
      read(p.name.text, id.getStart());
    } else hand(ts.SyntaxKind[p.kind], id);
  }
}

function tagOf(name) {
  if (ts.isIdentifier(name)) {
    const s = name.text;
    return { tag: s, kind: /^[a-z]/.test(s) || s.includes('-') ? 'Intrinsic' : 'Identifier', root: name };
  }
  if (ts.isJsxNamespacedName(name)) return { tag: `${name.namespace.text}:${name.name.text}`, kind: 'Intrinsic' };
  if (name.kind === ts.SyntaxKind.ThisKeyword) return { tag: 'this', kind: 'Identifier' };
  if (ts.isPropertyAccessExpression(name)) {
    const parts = []; let e = name;
    while (ts.isPropertyAccessExpression(e)) { parts.unshift(e.name.text); e = e.expression; }
    parts.unshift(e.kind === ts.SyntaxKind.ThisKeyword ? 'this' : e.text);
    return { tag: parts.join('.'), kind: 'Member', root: ts.isIdentifier(e) ? e : null };
  }
  return { tag: '?', kind: '?' };
}

function scopeOf(root) {
  if (!root) return 'none';
  const sym = checker.getSymbolAtLocation(root);
  if (!sym || !sym.declarations || !sym.declarations.length) return 'unresolved';
  const d = sym.declarations[0];
  if (ts.isImportSpecifier(d) || ts.isImportClause(d) || ts.isNamespaceImport(d)) return 'module';
  let s = d;
  while (s && !ts.isSourceFile(s.parent) && !(ts.isVariableDeclarationList(s) && ts.isVariableStatement(s.parent) && ts.isSourceFile(s.parent.parent))) {
    if (ts.isFunctionLike(s.parent) || ts.isBlock(s.parent) || ts.isClassLike(s.parent) || ts.isCatchClause(s.parent) || ts.isForOfStatement(s.parent) || ts.isForStatement(s.parent)) return 'inner';
    s = s.parent;
  }
  return 'module';
}

function oneFile(file) {
  const sf = program.getSourceFile(file);
  const out = { file, comp: null, usages: [] };
  const c = findComp(sf);
  let fn = c && (c.fn || null);
  if (!c) out.comp = { kind: 'missing' };
  else if (c.nobody) out.comp = { kind: 'nobody' };
  else if (c.cls) out.comp = { kind: 'class' };
  else if (c.unknownCall !== undefined) {
    out.comp = { kind: 'unknownCall', callee: c.unknownCall };
    // The first function argument is the body only when it has JSX in it; otherwise it is not the component.
    if (c.first) {
      let jsx = false;
      const v = (n) => { if (ts.isJsxElement(n) || ts.isJsxSelfClosingElement(n) || ts.isJsxFragment(n)) jsx = true; ts.forEachChild(n, v); };
      v(c.first);
      out.comp.firstIsRender = jsx && c.first.parameters.length > 0;
      if (out.comp.firstIsRender) fn = c.first;
    }
  } else if (c.other) out.comp = { kind: 'other', what: c.other };
  let t = null;
  if (fn) { t = truthOf(fn); out.comp = Object.assign(out.comp || {}, { kind: out.comp ? out.comp.kind : 'fn' }); if (!out.comp.kind || out.comp.kind === 'fn') out.comp.kind = 'fn'; }

  // Tag symbols and member tag roots, by binding.
  const tagSyms = new Set(), memberTags = new Set(), propPassed = new Set();
  const all = [];
  const collect = (n) => {
    if (ts.isJsxOpeningElement(n) || ts.isJsxSelfClosingElement(n)) {
      all.push(n);
      const tn = n.tagName;
      if (ts.isIdentifier(tn)) { const s = checker.getSymbolAtLocation(tn); if (s) tagSyms.add(s); }
      if (ts.isPropertyAccessExpression(tn) && ts.isIdentifier(tn.expression)) {
        const s = checker.getSymbolAtLocation(tn.expression); if (s) memberTags.add(s.name + '#' + tn.name.text + '#' + (s.declarations?.[0]?.pos));
      }
      for (const a of n.attributes.properties) {
        if (ts.isJsxAttribute(a) && a.initializer && ts.isJsxExpression(a.initializer) && a.initializer.expression && ts.isIdentifier(a.initializer.expression)) {
          const s = checker.getSymbolAtLocation(a.initializer.expression); if (s) propPassed.add(s);
        }
      }
    }
    ts.forEachChild(n, collect);
  };
  collect(sf);
  // The symbol a function or class is bound to, through wrappers, call arguments, branches and factories.
  const bindingOf = (f) => {
    if ((ts.isFunctionDeclaration(f) || ts.isClassDeclaration(f)) && f.name) return { sym: checker.getSymbolAtLocation(f.name) };
    let n = f;
    for (;;) {
      const p = n.parent;
      if (WRAP.has(p.kind) || (ts.isCallExpression(p) && p.arguments.includes(n)) || (ts.isConditionalExpression(p) && p.condition !== n) ||
          (ts.isBinaryExpression(p) && [ts.SyntaxKind.QuestionQuestionToken, ts.SyntaxKind.BarBarToken].includes(p.operatorToken.kind)) ||
          (ts.isArrowFunction(p) && p.body === n)) { n = p; continue; }
      if (ts.isVariableDeclaration(p) && p.initializer === n && ts.isIdentifier(p.name)) return { sym: checker.getSymbolAtLocation(p.name) };
      if (ts.isBinaryExpression(p) && p.operatorToken.kind === ts.SyntaxKind.EqualsToken && p.right === n && ts.isIdentifier(p.left)) return { sym: checker.getSymbolAtLocation(p.left) };
      if (ts.isPropertyAssignment(p) && ts.isIdentifier(p.name) && ts.isObjectLiteralExpression(p.parent) && ts.isVariableDeclaration(p.parent.parent) && ts.isIdentifier(p.parent.parent.name)) {
        const s = checker.getSymbolAtLocation(p.parent.parent.name);
        return { member: s.name + '#' + p.name.text + '#' + s.declarations?.[0]?.pos };
      }
      return null;
    }
  };
  const nestedKind = (f) => {
    const b = bindingOf(f);
    if (!b) return null;
    if (b.sym && tagSyms.has(b.sym)) return 'tag';
    if (b.member && memberTags.has(b.member)) return 'member-tag';
    if (b.sym && propPassed.has(b.sym)) return 'prop-passed';
    return null;
  };
  const ownerOf = (el) => {
    for (let n = el.parent; n; n = n.parent) {
      if (n === fn) return 'comp';
      if ((isFn(n) || ts.isClassLike(n)) && fn && n.pos >= fn.pos && n.end <= fn.end) {
        const k = nestedKind(n); if (k) return 'nested:' + k;
      }
    }
    return 'file';
  };
  const shape = (el, forComp) => {
    const tg = tagOf(el.tagName);
    const attrs = el.attributes.properties.map((a) => {
      if (ts.isJsxSpreadAttribute(a)) {
        const e = peel(a.expression);
        let of = 'Other';
        if (t && ts.isIdentifier(e)) { const k = t.tracked.get(checker.getSymbolAtLocation(e)); if (k) of = k === 'props' ? 'Props' : 'Rest'; }
        return forComp ? { spread: of } : '...';
      }
      const n = ts.isJsxNamespacedName(a.name) ? `${a.name.namespace.text}:${a.name.name.text}` : a.name.text;
      if (!forComp) return n;
      let prop = null;
      if (t && a.initializer && ts.isJsxExpression(a.initializer) && a.initializer.expression) {
        const e = peel(a.initializer.expression);
        if (ts.isIdentifier(e)) prop = t.locals.get(checker.getSymbolAtLocation(e)) ?? null;
        else if ((ts.isPropertyAccessExpression(e) || ts.isElementAccessExpression(e)) && ts.isIdentifier(peel(e.expression)) &&
                 t.tracked.get(checker.getSymbolAtLocation(peel(e.expression)))) {
          if (ts.isPropertyAccessExpression(e)) prop = e.name.text;
          else if (ts.isStringLiteral(e.argumentExpression)) prop = e.argumentExpression.text;
        }
      }
      return { n, prop };
    });
    return { tag: tg.tag, kind: tg.kind, scope: scopeOf(tg.root), attrs };
  };
  const elements = [];
  for (const el of all) {
    const o = ownerOf(el);
    if (o === 'comp') elements.push(shape(el, true));
    else {
      out.usages.push(Object.assign(shape(el, false), { owner: o }));
      if (t && o.startsWith('nested')) for (const s of t.spreads) if (s.node.parent.parent === el) { t.handoff = true; t.why.push('spread in nested component ' + o); }
    }
  }
  if (t) Object.assign(out.comp, { reads: t.readKeys, handoff: t.handoff, why: t.why, propsSpread: t.propsSpread, elements });
  return out;
}

for (const f of files) {
  try { console.log(JSON.stringify(oneFile(f))); } catch (e) { console.log(JSON.stringify({ file: f, error: String(e.stack) })); }
}

