#!/usr/bin/env python3
"""Scratch: diffs the extractor's BODYFACTS/USAGES dump with oracle.jsonl. Usage: compare.py <raw-dump> <label>"""
import json, sys, collections, os

raw, label = sys.argv[1], sys.argv[2]
HERE = os.path.dirname(os.path.abspath(__file__))
oracle = {}
for line in open(os.path.join(HERE, "oracle.jsonl")):
    r = json.loads(line)
    oracle[os.path.realpath(os.path.join(HERE, r["file"]))] = r
maps, usages = collections.defaultdict(list), {}
for line in open(raw):
    if line.startswith("BODYFACTS "):
        r = json.loads(line[10:]); maps[os.path.realpath(r["file"])].append(r)
    elif line.startswith("USAGES "):
        r = json.loads(line[7:]); usages[os.path.realpath(r["file"])] = r["usages"]

def ext_tag(t):
    (k, v), = t.items()
    return k, v

def tag_expect(o):
    # What the extractor's JsxTag should be for an oracle element.
    if o["kind"] in ("Identifier", "Member") and o["scope"] == "inner":
        return ("Scoped", o["tag"])
    return (o["kind"], o["tag"])

def attr_ext(a):
    if "Named" in a: return ("N", a["Named"]["name"], a["Named"]["prop"])
    return ("S", a["Spread"])

def attr_orc(a):
    if "spread" in a: return ("S", a["spread"])
    return ("N", a["n"], a["prop"])

findings = collections.defaultdict(list)
def flag(cls, fid, detail):
    findings[cls].append((fid, detail))

for path, o in sorted(oracle.items()):
    fid = os.path.basename(path)[:-4]
    ms = maps.get(path, [])
    m = next((x for x in ms if x["name"] == "Comp"), None) or (ms[0] if len(ms) == 1 else None)
    comp = o["comp"]
    body = m and m["body"]
    if comp["kind"] in ("nobody", "class", "other") or (comp["kind"] == "unknownCall" and not comp.get("firstIsRender")):
        if body is not None and not body["handed_on"]:
            flag("E-complete-for-non-body", fid, f"oracle {comp}; extractor reads={body['reads']} complete")
        continue
    if comp["kind"] != "fn" and not comp.get("firstIsRender"):
        continue
    if m is None:
        flag("X-no-mapping", fid, [x["name"] for x in ms]); continue
    if body is None:
        flag("X-no-facts", fid, m["name"]); continue
    oreads, ereads = comp["reads"], body["reads"]
    extra = [k for k in ereads if k not in oreads]
    if extra: flag("A-extra-read", fid, f"extra={extra} oracle={oreads}")
    handoff = comp["handoff"] or (label == "b4fb" and comp["propsSpread"])
    if not body["handed_on"]:
        missing = [k for k in oreads if k not in ereads]
        if missing: flag("B-missing-read", fid, f"missing={missing} ext={ereads}")
        if handoff: flag("E-escape-claimed-complete", fid, f"why={comp['why']} spread={comp['propsSpread']}")
        common = [k for k in ereads if k in oreads]
        if [k for k in oreads if k in common] != common: flag("D-read-order", fid, f"ext={ereads} oracle={oreads}")
    # elements of the component
    eel = [(ext_tag(e["tag"]), [attr_ext(a) for a in e["attributes"]]) for e in body["elements"]]
    oel = [(tag_expect(e), [attr_orc(a) for a in e["attrs"]]) for e in comp["elements"]]
    def norm(t):  # b4fb has no Scoped: compare by name, report scope separately
        return ("Identifier" if t[0] == "Scoped" else t[0], t[1])
    etags, otags = [norm(t) for t, _ in eel], [norm(t) for t, _ in oel]
    if etags != otags:
        if sorted(map(str, etags)) == sorted(map(str, otags)): flag("D-element-order", fid, f"ext={etags} oracle={otags}")
        else: flag("C-element-owner", fid, f"ext={etags} oracle={otags}")
    else:
