            if ea != oa: flag("F-attrs", fid, f"{et[1]} ext={ea} oracle={oa}")

for path, o in sorted(oracle.items()):
    fid = os.path.basename(path)[:-4]
    eu = [(ext_tag(u["tag"]), [a.get("Named", "...") if isinstance(a, dict) else "..." for a in u["attributes"]]) for u in usages.get(path, [])]
    ou = [(tag_expect(u), u["attrs"], u["owner"]) for u in o["usages"]]
    def norm(t): return ("Identifier" if t[0] == "Scoped" else t[0], t[1])
    if [norm(t) for t, _ in eu] != [norm(t) for t, _, _ in ou]:
        flag("C-usage-owner/order", fid, f"ext={[t for t,_ in eu]} oracle={[(t, w) for t,_,w in ou]}")
    else:
        for (et, ea), (ot, oa, ow) in zip(eu, ou):
            if et != ot: flag("C3-usage-scope", fid, f"ext={et} oracle={ot} owner={ow}")
            if ea != oa: flag("F-usage-attrs", fid, f"ext={ea} oracle={oa}")

print(f"== {label}: {len(oracle)} fixtures")
